import type { CSSProperties } from "react";

// Generated by strokit. Colors follow --sk-stroke; prefers-reduced-motion shows the final frame.
const css = `
.sk-kp99z2-0 {
  stroke: var(--sk-stroke, #000000);
  stroke-dasharray: 0.42 1;
  animation: sk-kp99z2-t0-yoyo calc(1400ms / var(--sk-speed, 1)) ease-in-out 0ms var(--sk-iterations, infinite) alternate both;
  animation-play-state: var(--sk-play-state, running);
}
@keyframes sk-kp99z2-t0-yoyo {
  0% {
    stroke-dashoffset: 0;
  }
  100% {
    stroke-dashoffset: -0.58;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sk-kp99z2 * {
    animation: none;
  }
  .sk-kp99z2-0 {
    stroke-dasharray: none;
  }
}
`;

export type BrandMarkProps = {
  /** Width and height (number = px). Defaults to the SVG's own size. */
  size?: number | string;
  /** Playback speed multiplier: 2 plays twice as fast. */
  speed?: number;
  /** true repeats forever, false plays once. Defaults to the exported animation. */
  loop?: boolean;
  paused?: boolean;
  className?: string;
  /** Accessible name. Defaults to "strokit". */
  label?: string;
};

export function BrandMark({
  size,
  speed = 1,
  loop,
  paused = false,
  className,
  label = "strokit",
}: BrandMarkProps) {
  const style = {
    "--sk-speed": speed,
    "--sk-play-state": paused ? "paused" : "running",
    ...(loop === undefined ? {} : { "--sk-iterations": loop ? "infinite" : 1 }),
  } as CSSProperties;

  return (
    <svg
      viewBox="0 0 64 64"
      width={size ?? 64}
      height={size ?? 64}
      className={className ? `sk-kp99z2 ${className}` : "sk-kp99z2"}
      style={style}
      role="img"
      aria-label={label}
    >
      <style>{css}</style>
      <title>{"strokit"}</title>
      <path d="M46 14 H26 A10 10 0 0 0 26 34 H38 A10 10 0 0 1 38 54 H18" fill="none" stroke="#000000" strokeWidth="7" strokeLinecap="square" strokeLinejoin="miter" pathLength="1" className="sk-kp99z2-0" />
    </svg>
  );
}
